from pyspark.sql import functions as F


def solve(employees):
    mapped = employees.replace({"ft": "full_time", "pt": "part_time", "contract": "contractor"}, subset=["employment_type"])
    tidy = F.regexp_replace(F.lower(F.trim("employment_type")), "[ -]", "_")
    return mapped.select("employee_id", tidy.alias("employment_type"))
